"use strict";
const octarine = require("octarine");

/**
 * Send a message to a tower. Returns the number of towers it passed.
 * @param {string} tower
 * @param {string} message
 */
function send(tower, message) {
  return octarine.shade(message).length % 7;
}

/** The towers between two points on the Grand Trunk. */
function towers(from, to) {
  return [from, "Sto Lat", to];
}

module.exports = { send, towers, GNU: "GNU Terry Pratchett" };
